-- Friday Relay PostgreSQL physical baseline.
-- Current lineage: friday-relay-postgres-v1 schema v10.
-- Frozen inventory digest: 706e92de1a7d6611fc46b7a2f70c709551ccc83b6f4785437b4f456c8cae8882.
-- This migration preserves PostgreSQL-only checks, deferred foreign keys, indexes, functions, and triggers that schema.prisma cannot express.
-- Existing environments adopt this migration only through a separately authorized physical no-op baseline procedure.
CREATE OR REPLACE FUNCTION "friday_relay_json_type"(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN RETURN jsonb_typeof(value::jsonb); EXCEPTION WHEN others THEN RETURN NULL; END $$;
CREATE TABLE IF NOT EXISTS "friday_relay_pg_schema_meta" (lineage text PRIMARY KEY, schema_version integer NOT NULL, inventory_digest text NOT NULL, applied_at text NOT NULL);
CREATE TABLE IF NOT EXISTS "shared_pg_release_transactions" (transaction_id text PRIMARY KEY, blue_green_group_id text NOT NULL, database_resource_id text NOT NULL, release_tag text NOT NULL, release_commit text NOT NULL, state_revision integer NOT NULL, phase text NOT NULL, canonical_target text NOT NULL, direct_dev_state text NOT NULL, schema_before integer NOT NULL, schema_after integer, state_json text NOT NULL, updated_at text NOT NULL);
ALTER TABLE "shared_pg_release_transactions" ADD COLUMN IF NOT EXISTS "direct_dev_state" text NOT NULL DEFAULT 'open';
CREATE UNIQUE INDEX IF NOT EXISTS "shared_pg_release_transactions_active_resource_unique" ON "shared_pg_release_transactions" (database_resource_id) WHERE phase NOT IN ('completed', 'failed');
CREATE TABLE IF NOT EXISTS "friday_relay_job_leases" (
     job_key text PRIMARY KEY,
     owner_id text NOT NULL,
     fencing_token bigint NOT NULL,
     lease_until_ms bigint NOT NULL,
     updated_at_ms bigint NOT NULL
   );
CREATE TABLE IF NOT EXISTS "friday_relay_shadow_risk_state" (
    guard_id text PRIMARY KEY,
    profile_digest text NOT NULL,
    revision bigint NOT NULL,
    window_started_at_ms bigint NOT NULL,
    request_starts_json text NOT NULL,
    updated_at text NOT NULL
  );
CREATE TABLE IF NOT EXISTS "friday_relay_shadow_risk_reservations" (
    reservation_id text PRIMARY KEY,
    guard_id text NOT NULL REFERENCES "friday_relay_shadow_risk_state" (guard_id) DEFERRABLE INITIALLY DEFERRED,
    status text NOT NULL CHECK (status IN ('active', 'settled', 'conservative')),
    reserved_credit_units bigint NOT NULL,
    settled_credit_units bigint,
    acquired_at_ms bigint NOT NULL,
    expires_at_ms bigint NOT NULL,
    terminal_at_ms bigint,
    terminal_evidence_digest text
  );
CREATE INDEX IF NOT EXISTS "friday_relay_shadow_risk_reservations_guard_status_idx"
    ON "friday_relay_shadow_risk_reservations" (guard_id, status, acquired_at_ms);
CREATE TABLE IF NOT EXISTS "abuse_rate_limit_counters" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "bucket" text COLLATE "C" NOT NULL, "subject_hash" text COLLATE "C" NOT NULL, "window_start" bigint NOT NULL, "window_seconds" integer NOT NULL, "count" integer NOT NULL, "blocked_until" bigint, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "access_point_price_tiers" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "access_point_price_id" text COLLATE "C" NOT NULL, "service_tier" text COLLATE "C" NOT NULL DEFAULT 'standard', "tier_key" text COLLATE "C" NOT NULL, "min_input_tokens" bigint NOT NULL, "max_input_tokens" bigint, "input_per_1m" double precision NOT NULL, "cached_input_per_1m" double precision NOT NULL, "cache_write_per_1m" double precision, "output_per_1m" double precision NOT NULL, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "access_point_prices" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "access_point_id" text COLLATE "C" NOT NULL, "input_per_1m" double precision NOT NULL, "cached_input_per_1m" double precision NOT NULL, "cache_write_per_1m" double precision, "output_per_1m" double precision NOT NULL, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "access_point_targets" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "access_point_id" text COLLATE "C" NOT NULL, "target_type" text COLLATE "C" NOT NULL, "target_access_point_id" text COLLATE "C", "target_provider_id" text COLLATE "C", "target_provider_model_name" text COLLATE "C", "position" integer NOT NULL, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "access_point_targets_type_check" CHECK ("target_type" IN ('access-point', 'provider-model')), CONSTRAINT "access_point_targets_status_check" CHECK ("status" IN ('enabled', 'disabled')), CONSTRAINT "access_point_targets_position_check" CHECK ("position" >= 0), CONSTRAINT "access_point_targets_ref_check" CHECK (
    ("target_type" = 'access-point' AND "target_access_point_id" IS DISTINCT FROM NULL AND "target_provider_id" IS NULL AND "target_provider_model_name" IS NULL)
    OR
    ("target_type" = 'provider-model' AND "target_access_point_id" IS NULL AND "target_provider_id" IS DISTINCT FROM NULL AND "target_provider_model_name" IS DISTINCT FROM NULL)
  ));
CREATE TABLE IF NOT EXISTS "access_points" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "owner_id" text COLLATE "C" NOT NULL, "scope_ref" text COLLATE "C" NOT NULL, "name" text COLLATE "C" NOT NULL, "description" text COLLATE "C", "api_family" text COLLATE "C" NOT NULL, "exposed_model" text COLLATE "C" NOT NULL, "target_model" text COLLATE "C" NOT NULL, "selector_id" text COLLATE "C" NOT NULL DEFAULT 'direct', "selector_behavior_version" integer NOT NULL DEFAULT 1, "selector_config_json" text COLLATE "C" NOT NULL DEFAULT '{}', "routing_revision" integer NOT NULL DEFAULT 1, "target_type" text COLLATE "C" NOT NULL, "target_id" text COLLATE "C", "target_provider_id" text COLLATE "C", "target_provider_model_name" text COLLATE "C", "priority" integer NOT NULL, "weight" integer NOT NULL, "fallback_order" integer NOT NULL, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "access_points_description_check" CHECK ("description" IS NULL OR length("description") <= 500));
CREATE TABLE IF NOT EXISTS "admin_grant_batch_items" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "batch_id" text COLLATE "C" NOT NULL, "target_user_id" text COLLATE "C" NOT NULL, "outcome" text COLLATE "C" NOT NULL, "reason_code" text COLLATE "C", "card_id" text COLLATE "C", "subscription_id" text COLLATE "C", "processed_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "admin_grant_batches" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "action_type" text COLLATE "C" NOT NULL, "reference_code" text COLLATE "C" NOT NULL, "plan_id" text COLLATE "C", "credit_product_id" text COLLATE "C", "expires_at" text COLLATE "C", "note" text COLLATE "C", "fallback_to_plan_card" integer NOT NULL DEFAULT 0, "requested_by_user_id" text COLLATE "C" NOT NULL, "idempotency_key_hash" text COLLATE "C" NOT NULL, "request_hash" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "completed_at" text COLLATE "C");
CREATE TABLE IF NOT EXISTS "agent_catalog_revisions" ("id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL, "revision" integer NOT NULL DEFAULT 0, CONSTRAINT "agent_catalog_revisions_singleton_check" CHECK ("id" = 1), CONSTRAINT "agent_catalog_revisions_revision_check" CHECK ("revision" >= 0));
CREATE TABLE IF NOT EXISTS "api_keys" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "user_id" text COLLATE "C" NOT NULL, "name" text COLLATE "C" NOT NULL, "key_hash" text COLLATE "C" NOT NULL, "key_prefix" text COLLATE "C" NOT NULL, "key_value" text COLLATE "C" NOT NULL, "status" text COLLATE "C" NOT NULL, "mcp_enabled" integer NOT NULL DEFAULT 0, "expires_at" text COLLATE "C", "revoked_at" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "api_keys_mcp_enabled_boolean_check" CHECK ("mcp_enabled" IN (0, 1)));
CREATE TABLE IF NOT EXISTS "audit_logs" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "actor_type" text COLLATE "C" NOT NULL, "actor_id" text COLLATE "C" NOT NULL, "action" text COLLATE "C" NOT NULL, "resource_type" text COLLATE "C" NOT NULL, "resource_id" text COLLATE "C" NOT NULL, "result" text COLLATE "C" NOT NULL, "request_id" text COLLATE "C", "source" text COLLATE "C" NOT NULL, "ip_hash" text COLLATE "C", "user_agent_hash" text COLLATE "C", "metadata_json" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "authority_grant_quotas" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "grant_id" text COLLATE "C" NOT NULL, "capability_code" text COLLATE "C" NOT NULL, "granted_units" bigint NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "authority_grant_quotas_capability_check" CHECK ("capability_code" = 'team.create'), CONSTRAINT "authority_grant_quotas_units_check" CHECK ("granted_units" BETWEEN 1 AND 1000));
CREATE TABLE IF NOT EXISTS "authority_grants" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "beneficiary_user_id" text COLLATE "C" NOT NULL, "role_domain" text COLLATE "C" NOT NULL, "role_code" text COLLATE "C" NOT NULL, "role_scope_id" text COLLATE "C", "source_kind" text COLLATE "C" NOT NULL, "source_purchase_id" text COLLATE "C", "source_product_code_snapshot" text COLLATE "C", "source_product_version_snapshot" integer, "source_origin_id_snapshot" text COLLATE "C", "max_current_owned_teams_snapshot" integer, "max_lifetime_created_teams_snapshot" integer, "issued_by_user_id" text COLLATE "C", "effective_start" text COLLATE "C" NOT NULL, "effective_end" text COLLATE "C", "lifecycle" text COLLATE "C" NOT NULL, "canceled_at" text COLLATE "C", "canceled_by_user_id" text COLLATE "C", "cancel_reason_code" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "authority_grants_role_check" CHECK ("role_domain" = 'platform' AND "role_code" IN ('owner', 'creator') AND "role_scope_id" IS NULL), CONSTRAINT "authority_grants_lifecycle_check" CHECK ("lifecycle" IN ('active', 'canceled')), CONSTRAINT "authority_grants_current_team_limit_check" CHECK ("max_current_owned_teams_snapshot" IS NULL OR "max_current_owned_teams_snapshot" BETWEEN 1 AND 1000), CONSTRAINT "authority_grants_lifetime_team_limit_check" CHECK ("max_lifetime_created_teams_snapshot" IS NULL OR "max_lifetime_created_teams_snapshot" BETWEEN 1 AND 1000), CONSTRAINT "authority_grants_cancel_shape_check" CHECK (
    ("lifecycle" = 'active' AND "canceled_at" IS NULL AND "canceled_by_user_id" IS NULL AND "cancel_reason_code" IS NULL)
    OR ("lifecycle" = 'canceled' AND "canceled_at" IS DISTINCT FROM NULL AND "canceled_by_user_id" IS DISTINCT FROM NULL AND "cancel_reason_code" IN ('security_response', 'fraud', 'product_correction', 'operator_error', 'refund', 'owner_handover'))
  ), CONSTRAINT "authority_grants_source_shape_check" CHECK (
    ("source_kind" = 'system_bootstrap' AND "role_code" = 'owner' AND "source_purchase_id" IS NULL AND "effective_end" IS NULL)
    OR ("source_kind" = 'product_purchase' AND "role_code" = 'creator' AND "source_purchase_id" IS DISTINCT FROM NULL AND "effective_end" IS DISTINCT FROM NULL)
    OR ("source_kind" = 'control_snapshot' AND "role_code" = 'creator' AND "source_purchase_id" IS NULL AND "source_product_code_snapshot" IS DISTINCT FROM NULL AND "source_product_version_snapshot" IS DISTINCT FROM NULL AND "source_origin_id_snapshot" IS DISTINCT FROM NULL AND "effective_end" IS DISTINCT FROM NULL)
  ));
CREATE TABLE IF NOT EXISTS "authority_products" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "code" text COLLATE "C" NOT NULL, "version" integer NOT NULL, "display_name" text COLLATE "C" NOT NULL, "effect_code" text COLLATE "C" NOT NULL, "grant_units" bigint NOT NULL, "purchase_amount_units" bigint NOT NULL, "grant_duration_seconds" integer NOT NULL, "max_lifetime_purchases_per_user" integer, "max_unconsumed_units_per_user" integer, "max_current_owned_teams" integer, "max_lifetime_created_teams" integer, "refund_mode" text COLLATE "C" NOT NULL, "refund_deadline_seconds" integer, "settlement_hold_seconds" integer NOT NULL, "seller_scope_ref" text COLLATE "C" NOT NULL, "lifecycle" text COLLATE "C" NOT NULL, "created_by_owner_user_id" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "authority_products_effect_check" CHECK ("effect_code" IN ('team_create_unit', 'team_custom_provider_access')), CONSTRAINT "authority_products_lifecycle_check" CHECK ("lifecycle" IN ('draft', 'listed', 'closed')), CONSTRAINT "authority_products_grant_units_check" CHECK ("grant_units" BETWEEN 1 AND 1000), CONSTRAINT "authority_products_purchase_amount_check" CHECK ("purchase_amount_units" BETWEEN 1 AND 9007199254740991), CONSTRAINT "authority_products_grant_duration_check" CHECK ("grant_duration_seconds" BETWEEN 1 AND 315360000), CONSTRAINT "authority_products_purchase_limit_check" CHECK ("max_lifetime_purchases_per_user" IS NULL OR "max_lifetime_purchases_per_user" BETWEEN 1 AND 1000000), CONSTRAINT "authority_products_unconsumed_limit_check" CHECK ("max_unconsumed_units_per_user" IS NULL OR "max_unconsumed_units_per_user" BETWEEN 1 AND 1000000), CONSTRAINT "authority_products_current_team_limit_check" CHECK ("max_current_owned_teams" IS NULL OR "max_current_owned_teams" BETWEEN 1 AND 1000), CONSTRAINT "authority_products_lifetime_team_limit_check" CHECK ("max_lifetime_created_teams" IS NULL OR "max_lifetime_created_teams" BETWEEN 1 AND 1000), CONSTRAINT "authority_products_settlement_hold_check" CHECK ("settlement_hold_seconds" BETWEEN 1 AND 31536000), CONSTRAINT "authority_products_refund_check" CHECK (
    ("refund_mode" = 'none' AND "refund_deadline_seconds" IS NULL)
    OR ("refund_mode" = 'unused_by_owner' AND "refund_deadline_seconds" > 0 AND "refund_deadline_seconds" <= "grant_duration_seconds" AND "refund_deadline_seconds" < "settlement_hold_seconds")
  ), CONSTRAINT "authority_products_effect_terms_check" CHECK (
    "effect_code" = 'team_create_unit'
    OR ("grant_units" = 1 AND "max_unconsumed_units_per_user" IS NULL
      AND "max_current_owned_teams" IS NULL AND "max_lifetime_created_teams" IS NULL
      AND "refund_mode" = 'none' AND "refund_deadline_seconds" IS NULL)
  ));
CREATE TABLE IF NOT EXISTS "authority_purchases" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "product_id" text COLLATE "C" NOT NULL, "buyer_user_id" text COLLATE "C" NOT NULL, "credit_account_id" text COLLATE "C" NOT NULL, "product_code" text COLLATE "C" NOT NULL, "product_version" integer NOT NULL, "product_display_name" text COLLATE "C" NOT NULL, "effect_code" text COLLATE "C" NOT NULL, "grant_units" bigint NOT NULL, "purchase_amount_units" bigint NOT NULL, "grant_duration_seconds" integer NOT NULL, "max_lifetime_purchases_per_user" integer, "max_unconsumed_units_per_user" integer, "max_current_owned_teams" integer, "max_lifetime_created_teams" integer, "refund_mode" text COLLATE "C" NOT NULL, "refund_deadline_seconds" integer, "settlement_hold_seconds" integer NOT NULL, "seller_scope_ref" text COLLATE "C" NOT NULL, "idempotency_key_hash" text COLLATE "C" NOT NULL, "request_hash" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "authority_purchases_effect_check" CHECK ("effect_code" IN ('team_create_unit', 'team_custom_provider_access')), CONSTRAINT "authority_purchases_grant_units_check" CHECK ("grant_units" BETWEEN 1 AND 1000), CONSTRAINT "authority_purchases_purchase_amount_check" CHECK ("purchase_amount_units" BETWEEN 1 AND 9007199254740991), CONSTRAINT "authority_purchases_grant_duration_check" CHECK ("grant_duration_seconds" BETWEEN 1 AND 315360000), CONSTRAINT "authority_purchases_purchase_limit_check" CHECK ("max_lifetime_purchases_per_user" IS NULL OR "max_lifetime_purchases_per_user" BETWEEN 1 AND 1000000), CONSTRAINT "authority_purchases_unconsumed_limit_check" CHECK ("max_unconsumed_units_per_user" IS NULL OR "max_unconsumed_units_per_user" BETWEEN 1 AND 1000000), CONSTRAINT "authority_purchases_current_team_limit_check" CHECK ("max_current_owned_teams" IS NULL OR "max_current_owned_teams" BETWEEN 1 AND 1000), CONSTRAINT "authority_purchases_lifetime_team_limit_check" CHECK ("max_lifetime_created_teams" IS NULL OR "max_lifetime_created_teams" BETWEEN 1 AND 1000), CONSTRAINT "authority_purchases_settlement_hold_check" CHECK ("settlement_hold_seconds" BETWEEN 1 AND 31536000), CONSTRAINT "authority_purchases_refund_check" CHECK (
    ("refund_mode" = 'none' AND "refund_deadline_seconds" IS NULL)
    OR ("refund_mode" = 'unused_by_owner' AND "refund_deadline_seconds" > 0 AND "refund_deadline_seconds" <= "grant_duration_seconds" AND "refund_deadline_seconds" < "settlement_hold_seconds")
  ), CONSTRAINT "authority_purchases_effect_terms_check" CHECK (
    "effect_code" = 'team_create_unit'
    OR ("grant_units" = 1 AND "max_unconsumed_units_per_user" IS NULL
      AND "max_current_owned_teams" IS NULL AND "max_lifetime_created_teams" IS NULL
      AND "refund_mode" = 'none' AND "refund_deadline_seconds" IS NULL)
  ));
CREATE TABLE IF NOT EXISTS "authority_refunds" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "authority_purchase_id" text COLLATE "C" NOT NULL, "authority_grant_id" text COLLATE "C" NOT NULL, "actor_owner_user_id" text COLLATE "C" NOT NULL, "reason_code" text COLLATE "C" NOT NULL, "idempotency_key_hash" text COLLATE "C" NOT NULL, "request_hash" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "authority_refunds_reason_check" CHECK ("reason_code" IN ('customer_request', 'duplicate_purchase', 'product_correction', 'operator_error')));
