CREATE TABLE IF NOT EXISTS "billing_events" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "request_id" text COLLATE "C" NOT NULL, "billing_subscription_id" text COLLATE "C", "billing_scope_ref" text COLLATE "C", "billable_price_id" text COLLATE "C" NOT NULL, "billable_price_source" text COLLATE "C" NOT NULL, "billable_price_tier_key" text COLLATE "C" NOT NULL DEFAULT 'legacy_flat', "operation_kind" text COLLATE "C" NOT NULL DEFAULT 'inference', "mcp_orchestration_run_id" text COLLATE "C", "mcp_tool_call_attempt_id" text COLLATE "C", "mcp_charge_units" bigint NOT NULL DEFAULT 0, "provider_model_cost_id" text COLLATE "C" NOT NULL, "provider_cost_tier_key" text COLLATE "C" NOT NULL DEFAULT 'legacy_flat', "input_tokens" bigint NOT NULL, "cached_input_tokens" bigint NOT NULL, "cache_write_tokens" bigint NOT NULL DEFAULT 0, "output_tokens" bigint NOT NULL, "total_tokens" bigint NOT NULL, "billable_amount" double precision NOT NULL, "provider_cost_amount" double precision NOT NULL, "gross_margin_amount" double precision NOT NULL, "usage_source" text COLLATE "C" NOT NULL, "billable_price_snapshot_json" text COLLATE "C" NOT NULL, "cost_price_snapshot_json" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "billing_events_operation_check" CHECK ("operation_kind" IN ('inference', 'orchestration_turn', 'mcp_tool')), CONSTRAINT "billing_events_mcp_charge_check" CHECK ("mcp_charge_units" >= 0 AND ("operation_kind" = 'mcp_tool' OR "mcp_charge_units" = 0)));
