CREATE TABLE IF NOT EXISTS "plan_mcp_tools" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "plan_id" text COLLATE "C" NOT NULL, "connector_id" text COLLATE "C" NOT NULL, "connector_revision" integer NOT NULL DEFAULT 1, "public_tool_alias" text COLLATE "C" NOT NULL, "upstream_tool_name" text COLLATE "C" NOT NULL, "input_schema_json" text COLLATE "C" NOT NULL DEFAULT '{}', "risk" text COLLATE "C" NOT NULL, "idempotent" integer NOT NULL DEFAULT 0, "auto_executable" integer NOT NULL DEFAULT 0, "charge_units" bigint NOT NULL DEFAULT 0, "max_argument_bytes" integer NOT NULL DEFAULT 32768, "max_result_bytes" integer NOT NULL DEFAULT 65536, "status" text COLLATE "C" NOT NULL DEFAULT 'enabled', "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "plan_mcp_tools_connector_revision_check" CHECK ("connector_revision" >= 1), CONSTRAINT "plan_mcp_tools_alias_check" CHECK (length(trim("public_tool_alias")) BETWEEN 1 AND 96), CONSTRAINT "plan_mcp_tools_upstream_name_check" CHECK (length(trim("upstream_tool_name")) BETWEEN 1 AND 200), CONSTRAINT "plan_mcp_tools_schema_check" CHECK (friday_relay_json_type("input_schema_json") IS DISTINCT FROM NULL AND friday_relay_json_type("input_schema_json") = 'object'), CONSTRAINT "plan_mcp_tools_risk_check" CHECK ("risk" IN ('read_only', 'consequential', 'write', 'admin', 'unknown')), CONSTRAINT "plan_mcp_tools_charge_check" CHECK ("charge_units" >= 0), CONSTRAINT "plan_mcp_tools_argument_limit_check" CHECK ("max_argument_bytes" BETWEEN 1 AND 1048576), CONSTRAINT "plan_mcp_tools_result_limit_check" CHECK ("max_result_bytes" BETWEEN 1 AND 4194304), CONSTRAINT "plan_mcp_tools_status_check" CHECK ("status" IN ('enabled', 'suspended')), CONSTRAINT "plan_mcp_tools_auto_execution_check" CHECK ("auto_executable" IN (0, 1) AND "idempotent" IN (0, 1)), CONSTRAINT "plan_mcp_tools_idempotent_boolean_check" CHECK ("idempotent" IN (0, 1)), CONSTRAINT "plan_mcp_tools_auto_executable_boolean_check" CHECK ("auto_executable" IN (0, 1)));
