" IS NULL) OR ("status" IN ('fulfilled','reversed') AND "card_id" IS DISTINCT FROM NULL AND "fulfilled_at" IS DISTINCT FROM NULL) OR ("status" IN ('payment_failed','cancelled','expired') AND "card_id" IS NULL AND "fulfilled_at" IS NULL)), CONSTRAINT "plan_purchase_orders_status_check" CHECK ("status" IN ('pending_payment','fulfilled','payment_failed','cancelled','expired','reversed')), CONSTRAINT "plan_purchase_orders_use_immediately_boolean_check" CHECK ("use_immediately" IN (0, 1)));
