CREATE TABLE IF NOT EXISTS "request_provider_attempts" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "request_id" text COLLATE "C" NOT NULL, "attempt_index" integer NOT NULL, "selector_access_point_id" text COLLATE "C" NOT NULL, "selector_id" text COLLATE "C" NOT NULL, "selector_behavior_version" integer NOT NULL, "routing_revision" integer NOT NULL, "candidate_id" text COLLATE "C" NOT NULL, "selector_target_edge_id" text COLLATE "C" NOT NULL, "path_target_edge_ids_json" text COLLATE "C" NOT NULL, "access_point_chain_ids_json" text COLLATE "C" NOT NULL, "provider_id" text COLLATE "C" NOT NULL, "provider_model_name" text COLLATE "C" NOT NULL, "outcome" text COLLATE "C" NOT NULL, "failure_class" text COLLATE "C", "output_committed" integer NOT NULL DEFAULT 0, "trusted_usage_source" text COLLATE "C", "started_at" text COLLATE "C" NOT NULL, "ended_at" text COLLATE "C", CONSTRAINT "request_provider_attempts_outcome_check" CHECK ("outcome" IN ('pending', 'succeeded', 'failed', 'aborted')), CONSTRAINT "request_provider_attempts_failure_class_check" CHECK ("failure_class" IS NULL OR "failure_class" IN ('connect_error', 'timeout', 'rate_limited', 'upstream_5xx', 'non_retryable')), CONSTRAINT "request_provider_attempts_usage_source_check" CHECK ("trusted_usage_source" IS NULL OR "trusted_usage_source" IN ('provider', 'response')), CONSTRAINT "request_provider_attempts_path_json_check" CHECK (friday_relay_json_type("path_target_edge_ids_json") IS DISTINCT FROM NULL AND friday_relay_json_type("path_target_edge_ids_json") = 'array' AND friday_relay_json_type("access_point_chain_ids_json") IS DISTINCT FROM NULL AND friday_relay_json_type("access_point_chain_ids_json") = 'array'), CONSTRAINT "request_provider_attempts_output_committed_boolean_check" CHECK ("output_committed" IN (0, 1)));
CREATE TABLE IF NOT EXISTS "resource_permissions" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "resource_type" text COLLATE "C" NOT NULL, "resource_id" text COLLATE "C" NOT NULL, "action" text COLLATE "C" NOT NULL, "subject_type" text COLLATE "C" NOT NULL, "subject_ref" text COLLATE "C" NOT NULL, "subject_role" text COLLATE "C", "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
