CREATE TABLE IF NOT EXISTS "scope_rate_limit_policies" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "scope_ref" text COLLATE "C" NOT NULL, "rate_limit_policy_id" text COLLATE "C" NOT NULL, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "seller_settlement_events" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "plan_subscription_id" text COLLATE "C", "authority_purchase_id" text COLLATE "C", "seller_scope_ref" text COLLATE "C" NOT NULL, "window_start" text COLLATE "C" NOT NULL, "window_end" text COLLATE "C" NOT NULL, "release_at" text COLLATE "C" NOT NULL, "event_type" text COLLATE "C" NOT NULL, "amount_units" bigint NOT NULL, "source_type" text COLLATE "C" NOT NULL, "source_id" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "seller_settlement_events_typed_source_check" CHECK (("plan_subscription_id" IS DISTINCT FROM NULL) <> ("authority_purchase_id" IS DISTINCT FROM NULL)));
CREATE TABLE IF NOT EXISTS "service_fulfillments" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "order_id" text COLLATE "C" NOT NULL, "effect_type" text COLLATE "C" NOT NULL, "target_type" text COLLATE "C", "target_id" text COLLATE "C", "status" text COLLATE "C" NOT NULL, "initiated_by_user_id" text COLLATE "C" NOT NULL, "completed_by_user_id" text COLLATE "C", "error_code" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, "completed_at" text COLLATE "C", "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "service_fulfillments_status_check" CHECK ("status" IN ('pending','ready','fulfilled','failed')));
CREATE TABLE IF NOT EXISTS "service_orders" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "buyer_user_id" text COLLATE "C" NOT NULL, "target_partner_team_id" text COLLATE "C", "product_id" text COLLATE "C" NOT NULL, "product_listing_id" text COLLATE "C" NOT NULL, "payment_channel_id" text COLLATE "C" NOT NULL, "product_code" text COLLATE "C" NOT NULL, "product_version" integer NOT NULL, "product_display_name" text COLLATE "C" NOT NULL, "fulfillment_effect" text COLLATE "C" NOT NULL, "duration_seconds" integer NOT NULL, "partner_plan_id" text COLLATE "C" NOT NULL, "purchase_intent" text COLLATE "C" NOT NULL, "expected_payment_amount_units" bigint NOT NULL, "confirmed_received_amount_units" bigint, "payment_asset" text COLLATE "C" NOT NULL, "payment_network" text COLLATE "C" NOT NULL, "normalized_transaction_reference_hash" text COLLATE "C", "transaction_reference_tail" text COLLATE "C", "payment_submitted_at" text COLLATE "C", "reviewed_by_user_id" text COLLATE "C", "reviewed_at" text COLLATE "C", "review_note" text COLLATE "C", "status" text COLLATE "C" NOT NULL, "create_idempotency_key_hash" text COLLATE "C" NOT NULL, "create_request_hash" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "service_orders_intent_check" CHECK ("purchase_intent" IN ('new','renew')), CONSTRAINT "service_orders_status_check" CHECK ("status" IN ('pending_payment','pending_review','paid','fulfilling','fulfilled','cancelled','rejected','failed')), CONSTRAINT "service_orders_amount_check" CHECK ("expected_payment_amount_units" > 0 AND ("confirmed_received_amount_units" IS NULL OR "confirmed_received_amount_units" > 0)));
CREATE TABLE IF NOT EXISTS "service_product_listings" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "product_id" text COLLATE "C" NOT NULL, "payment_channel_id" text COLLATE "C" NOT NULL, "price_amount_units" bigint NOT NULL, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "service_product_listings_price_check" CHECK ("price_amount_units" > 0), CONSTRAINT "service_product_listings_status_check" CHECK ("status" IN ('enabled','disabled')));
CREATE TABLE IF NOT EXISTS "service_products" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "code" text COLLATE "C" NOT NULL, "version" integer NOT NULL, "display_name" text COLLATE "C" NOT NULL, "description" text COLLATE "C", "fulfillment_effect" text COLLATE "C" NOT NULL, "duration_seconds" integer NOT NULL, "partner_plan_id" text COLLATE "C" NOT NULL, "status" text COLLATE "C" NOT NULL, "created_by_user_id" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "service_products_effect_check" CHECK ("fulfillment_effect" = 'partner_team_annual'), CONSTRAINT "service_products_duration_check" CHECK ("duration_seconds" > 0 AND "partner_plan_id" IS DISTINCT FROM NULL), CONSTRAINT "service_products_status_check" CHECK ("status" IN ('enabled','disabled')));
CREATE TABLE IF NOT EXISTS "stripe_webhook_events" ("event_id" text COLLATE "C" PRIMARY KEY NOT NULL, "event_type" text COLLATE "C" NOT NULL, "livemode" integer NOT NULL, "checkout_session_tail" text COLLATE "C", "topup_id" text COLLATE "C", "plan_purchase_order_id" text COLLATE "C", "status" text COLLATE "C" NOT NULL, "error_code" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, "processed_at" text COLLATE "C", CONSTRAINT "stripe_webhook_events_resource_shape_check" CHECK (NOT ("topup_id" IS DISTINCT FROM NULL AND "plan_purchase_order_id" IS DISTINCT FROM NULL)), CONSTRAINT "stripe_webhook_events_status_shape_check" CHECK (("status" IN ('received','failed') AND "processed_at" IS NULL) OR ("status" IN ('succeeded','ignored') AND "processed_at" IS DISTINCT FROM NULL)), CONSTRAINT "stripe_webhook_events_livemode_boolean_check" CHECK ("livemode" IN (0, 1)));
CREATE TABLE IF NOT EXISTS "team_deletion_lifecycles" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "team_id" text COLLATE "C" NOT NULL, "requested_at" text COLLATE "C" NOT NULL, "requested_by_user_id" text COLLATE "C" NOT NULL, "purge_not_before" text COLLATE "C" NOT NULL, "archive_status" text COLLATE "C" NOT NULL DEFAULT 'pending', "archive_manifest_id" text COLLATE "C", "archive_manifest_object_key" text COLLATE "C", "archive_manifest_sha256" text COLLATE "C", "archive_coverage_json" text COLLATE "C", "archived_at" text COLLATE "C", "cancelled_at" text COLLATE "C", "purged_at" text COLLATE "C", CONSTRAINT "team_deletion_lifecycles_archive_status_check" CHECK ("archive_status" IN ('pending','verified','failed')));
CREATE TABLE IF NOT EXISTS "team_invite_links" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "team_id" text COLLATE "C" NOT NULL, "created_by_user_id" text COLLATE "C" NOT NULL, "max_uses" integer, "used_count" integer, "active_limit_exempt" integer NOT NULL DEFAULT 0, "status" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "team_invite_links_capacity_check" CHECK (
    ("max_uses" IS NULL AND ("used_count" IS NULL OR "used_count" >= 0))
    OR ("max_uses" BETWEEN 1 AND 1000 AND "used_count" BETWEEN 0 AND "max_uses")
  ), CONSTRAINT "team_invite_links_enabled_capacity_check" CHECK ("status" = 'disabled' OR ("used_count" IS DISTINCT FROM NULL AND ("max_uses" IS NULL OR "used_count" < "max_uses"))), CONSTRAINT "team_invite_links_active_limit_exempt_check" CHECK ("active_limit_exempt" IN (0, 1)));
CREATE TABLE IF NOT EXISTS "team_memberships" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "team_id" text COLLATE "C" NOT NULL, "user_id" text COLLATE "C" NOT NULL, "roles_json" text COLLATE "C" NOT NULL DEFAULT '["viewer"]', "by_invite_link" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS "team_provider_entitlements" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "team_id" text COLLATE "C" NOT NULL, "source_kind" text COLLATE "C" NOT NULL, "source_authority_purchase_id" text COLLATE "C", "source_authority_product_id" text COLLATE "C", "source_product_code_snapshot" text COLLATE "C", "source_product_version_snapshot" integer, "source_product_display_name_snapshot" text COLLATE "C", "buyer_user_id" text COLLATE "C", "issued_by_user_id" text COLLATE "C", "effective_start" text COLLATE "C" NOT NULL, "effective_end" text COLLATE "C", "lifecycle" text COLLATE "C" NOT NULL, "canceled_at" text COLLATE "C", "canceled_by_user_id" text COLLATE "C", "cancel_reason_code" text COLLATE "C", "idempotency_key_hash" text COLLATE "C", "request_hash" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "team_provider_entitlements_source_check" CHECK (
    ("source_kind" = 'product_purchase' AND "source_authority_purchase_id" IS DISTINCT FROM NULL
      AND "source_authority_product_id" IS DISTINCT FROM NULL AND "buyer_user_id" IS DISTINCT FROM NULL
      AND "issued_by_user_id" IS NULL AND "effective_end" IS DISTINCT FROM NULL
      AND "idempotency_key_hash" IS NULL AND "request_hash" IS NULL)
    OR ("source_kind" = 'admin_grant' AND "source_authority_purchase_id" IS NULL
      AND "source_authority_product_id" IS DISTINCT FROM NULL AND "buyer_user_id" IS NULL
      AND "issued_by_user_id" IS DISTINCT FROM NULL AND "effective_end" IS DISTINCT FROM NULL
      AND "idempotency_key_hash" IS DISTINCT FROM NULL AND "request_hash" IS DISTINCT FROM NULL)
    OR ("source_kind" = 'legacy_migration' AND "source_authority_purchase_id" IS NULL
      AND "source_authority_product_id" IS NULL AND "source_product_code_snapshot" IS NULL
      AND "source_product_version_snapshot" IS NULL AND "source_product_display_name_snapshot" IS NULL
      AND "buyer_user_id" IS NULL AND "issued_by_user_id" IS NULL
      AND "effective_end" IS NULL AND "idempotency_key_hash" IS NULL AND "request_hash" IS NULL)
  ), CONSTRAINT "team_provider_entitlements_snapshot_check" CHECK (
    "source_kind" = 'legacy_migration'
    OR ("source_product_code_snapshot" IS DISTINCT FROM NULL AND "source_product_version_snapshot" IS DISTINCT FROM NULL
      AND "source_product_display_name_snapshot" IS DISTINCT FROM NULL)
  ), CONSTRAINT "team_provider_entitlements_period_check" CHECK ("effective_end" IS NULL OR "effective_start" < "effective_end"), CONSTRAINT "team_provider_entitlements_lifecycle_check" CHECK ("lifecycle" IN ('active', 'canceled')), CONSTRAINT "team_provider_entitlements_cancel_shape_check" CHECK (
    ("lifecycle" = 'active' AND "canceled_at" IS NULL AND "canceled_by_user_id" IS NULL AND "cancel_reason_code" IS NULL)
    OR ("lifecycle" = 'canceled' AND "canceled_at" IS DISTINCT FROM NULL AND "canceled_by_user_id" IS DISTINCT FROM NULL
      AND "cancel_reason_code" IN ('security_response', 'fraud', 'product_correction', 'operator_error'))
  ));
CREATE TABLE IF NOT EXISTS "teams" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "owner_id" text COLLATE "C" NOT NULL, "name" text COLLATE "C" NOT NULL, "status" text COLLATE "C" NOT NULL, "team_owner_can_manage_member_api_key_limit" integer NOT NULL DEFAULT 0, "team_owner_can_manage_member_credit" integer NOT NULL DEFAULT 0, "team_owner_can_create_custom_provider" integer NOT NULL DEFAULT 0, "team_owner_can_create_access_point" integer NOT NULL DEFAULT 0, "invite_email_domain_pattern" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL);
