CREATE TABLE IF NOT EXISTS "web_registration_settings" ("id" text COLLATE "C" PRIMARY KEY NOT NULL, "default_team_id" text COLLATE "C", "registration_invite_link_id" text COLLATE "C", "updated_by_user_id" text COLLATE "C", "created_at" text COLLATE "C" NOT NULL, "updated_at" text COLLATE "C" NOT NULL, CONSTRAINT "web_registration_settings_singleton_check" CHECK ("id" = 'global'), CONSTRAINT "web_registration_settings_reference_pair_check" CHECK (("default_team_id" IS NULL AND "registration_invite_link_id" IS NULL) OR ("default_team_id" IS DISTINCT FROM NULL AND "registration_invite_link_id" IS DISTINCT FROM NULL)));
CREATE TABLE IF NOT EXISTS "webauthn_ceremonies" ("session_hash" text COLLATE "C" PRIMARY KEY NOT NULL, "challenge_hash" text COLLATE "C" NOT NULL, "purpose" text COLLATE "C" NOT NULL, "surface" text COLLATE "C" NOT NULL, "user_id" text COLLATE "C", "expected_auth_version" integer, "rp_id" text COLLATE "C" NOT NULL, "origin" text COLLATE "C" NOT NULL, "passkey_name" text COLLATE "C", "expires_at" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL, CONSTRAINT "webauthn_ceremonies_purpose_check" CHECK ("purpose" IN ('registration','authentication')), CONSTRAINT "webauthn_ceremonies_surface_check" CHECK ("surface" IN ('web','admin')), CONSTRAINT "webauthn_ceremonies_binding_check" CHECK (
    ("purpose" = 'registration' AND "user_id" IS DISTINCT FROM NULL AND "expected_auth_version" >= 1 AND "passkey_name" IS DISTINCT FROM NULL)
    OR ("purpose" = 'authentication' AND "user_id" IS NULL AND "expected_auth_version" IS NULL AND "passkey_name" IS NULL)
  ));
CREATE TABLE IF NOT EXISTS "webauthn_user_handles" ("user_id" text COLLATE "C" PRIMARY KEY NOT NULL, "user_handle" text COLLATE "C" NOT NULL, "created_at" text COLLATE "C" NOT NULL);
