CREATE OR REPLACE FUNCTION "friday_relay_reject_immutable_update"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE allowed text[] := ARRAY(SELECT TG_ARGV[arg_index] FROM generate_series(1, TG_NARGS - 1) AS arg_index); BEGIN IF EXISTS (SELECT 1 FROM jsonb_each(to_jsonb(OLD)) AS old_row(key, value) FULL JOIN jsonb_each(to_jsonb(NEW)) AS new_row USING (key) WHERE NOT (COALESCE(old_row.key, new_row.key) = ANY(allowed)) AND old_row.value IS DISTINCT FROM new_row.value) THEN RAISE EXCEPTION '%', TG_ARGV[0] USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION "friday_relay_reject_delete"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = '55000'; END $$;
