CREATE OR REPLACE FUNCTION "friday_relay_validate_plan_payment_listing_status"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT (OLD.status IS NOT DISTINCT FROM NEW.status OR (OLD.status = 'enabled' AND NEW.status = 'disabled')) THEN RAISE EXCEPTION 'Plan payment listing cannot be re-enabled' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "plan_payment_listings_status_transition" ON "plan_payment_listings";
CREATE TRIGGER "plan_payment_listings_status_transition" BEFORE UPDATE OF status ON "plan_payment_listings" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_plan_payment_listing_status"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_plan_purchase_order_transition"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT (OLD.status IS NOT DISTINCT FROM NEW.status OR (OLD.status = 'pending_payment' AND NEW.status IN ('fulfilled','payment_failed','cancelled','expired')) OR (OLD.status = 'fulfilled' AND NEW.status = 'reversed')) OR NOT (OLD.checkout_session_id IS NOT DISTINCT FROM NEW.checkout_session_id OR (OLD.checkout_session_id IS NULL AND NEW.checkout_session_id IS NOT NULL)) OR NOT (OLD.payment_intent_id IS NOT DISTINCT FROM NEW.payment_intent_id OR (OLD.payment_intent_id IS NULL AND NEW.payment_intent_id IS NOT NULL)) OR NOT (OLD.card_id IS NOT DISTINCT FROM NEW.card_id OR (OLD.card_id IS NULL AND NEW.card_id IS NOT NULL)) OR NOT (OLD.credit_ledger_event_id IS NOT DISTINCT FROM NEW.credit_ledger_event_id OR (OLD.credit_ledger_event_id IS NULL AND NEW.credit_ledger_event_id IS NOT NULL)) OR NOT (OLD.subscription_id IS NOT DISTINCT FROM NEW.subscription_id OR (OLD.subscription_id IS NULL AND NEW.subscription_id IS NOT NULL)) THEN RAISE EXCEPTION 'Plan purchase order state transition is invalid' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "plan_purchase_orders_state_transition" ON "plan_purchase_orders";
CREATE TRIGGER "plan_purchase_orders_state_transition" BEFORE UPDATE ON "plan_purchase_orders" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_plan_purchase_order_transition"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_card_transition"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.card_type IS DISTINCT FROM NEW.card_type OR OLD.issuance_type IS DISTINCT FROM NEW.issuance_type OR OLD.plan_id IS DISTINCT FROM NEW.plan_id OR OLD.credit_product_id IS DISTINCT FROM NEW.credit_product_id OR OLD.credit_amount_units IS DISTINCT FROM NEW.credit_amount_units OR OLD.created_at IS DISTINCT FROM NEW.created_at OR OLD.expires_at IS DISTINCT FROM NEW.expires_at OR OLD.replaces_card_id IS DISTINCT FROM NEW.replaces_card_id OR NOT ((OLD.used_at IS NULL AND NEW.used_at IS NULL AND OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id AND OLD.invalidated_at IS NULL AND NEW.invalidated_at IS NULL AND OLD.invalidation_reason IS NOT DISTINCT FROM NEW.invalidation_reason) OR (OLD.used_at IS NULL AND NEW.used_at IS NOT NULL AND OLD.owner_user_id IS NOT DISTINCT FROM NEW.owner_user_id AND OLD.invalidated_at IS NULL AND NEW.invalidated_at IS NULL AND OLD.invalidation_reason IS NOT DISTINCT FROM NEW.invalidation_reason) OR (OLD.owner_user_id IS NOT DISTINCT FROM NEW.owner_user_id AND OLD.used_at IS NOT DISTINCT FROM NEW.used_at AND OLD.invalidated_at IS NULL AND NEW.invalidated_at IS NOT NULL AND length(trim(NEW.invalidation_reason)) > 0)) THEN RAISE EXCEPTION 'cards invalid state transition' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "cards_controlled_update" ON "cards";
CREATE TRIGGER "cards_controlled_update" BEFORE UPDATE ON "cards" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_card_transition"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_card_replacement"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.replaces_card_id IS NOT NULL AND (NEW.card_type <> 'plan' OR NEW.replaces_card_id = NEW.id) THEN RAISE EXCEPTION 'cards invalid replacement lineage' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "cards_replacement_insert" ON "cards";
CREATE TRIGGER "cards_replacement_insert" BEFORE INSERT ON "cards" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_card_replacement"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_pipeline_revision"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.setting_revision IS DISTINCT FROM OLD.setting_revision + 1 OR (NEW.config_json IS NOT DISTINCT FROM OLD.config_json AND NEW.config_revision IS NOT DISTINCT FROM OLD.config_revision) OR (NEW.config_json IS DISTINCT FROM OLD.config_json AND NEW.config_revision IS DISTINCT FROM OLD.config_revision + 1) THEN RAISE EXCEPTION 'pipeline_plugin_settings revisions must increase monotonically' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "pipeline_plugin_settings_revision_update" ON "pipeline_plugin_settings";
CREATE TRIGGER "pipeline_plugin_settings_revision_update" BEFORE UPDATE ON "pipeline_plugin_settings" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_pipeline_revision"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_provider_attempt_terminal"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.outcome <> 'pending' OR NEW.outcome NOT IN ('succeeded','failed','aborted') OR NEW.ended_at IS NULL OR (NEW.outcome = 'succeeded' AND (NEW.failure_class IS NOT NULL OR NEW.trusted_usage_source IS NOT NULL)) OR (NEW.outcome = 'aborted' AND NEW.failure_class IS NOT NULL) OR (NEW.outcome = 'failed' AND NEW.failure_class IS NULL) THEN RAISE EXCEPTION 'Provider Attempt terminal transition is invalid' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "request_provider_attempts_terminal_update" ON "request_provider_attempts";
CREATE TRIGGER "request_provider_attempts_terminal_update" BEFORE UPDATE ON "request_provider_attempts" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_provider_attempt_terminal"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_request_log_update"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.api_key_id IS DISTINCT FROM NEW.api_key_id OR OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.request_path IS DISTINCT FROM NEW.request_path OR OLD.ingress_hostname IS DISTINCT FROM NEW.ingress_hostname OR OLD.req_model IS DISTINCT FROM NEW.req_model OR OLD.ingress_plugins_json IS DISTINCT FROM NEW.ingress_plugins_json OR OLD.started_at IS DISTINCT FROM NEW.started_at OR NOT (OLD.pipeline_plugins_json IS NOT DISTINCT FROM NEW.pipeline_plugins_json OR (OLD.pipeline_plugins_json = '{"schemaVersion":1,"planRevision":"pending","invocations":[]}' AND NEW.pipeline_plugins_json IS DISTINCT FROM OLD.pipeline_plugins_json)) OR NOT (OLD.team_id IS NOT DISTINCT FROM NEW.team_id OR (OLD.team_id IS NULL AND NEW.team_id IS NOT NULL)) OR NOT (OLD.plan_id IS NOT DISTINCT FROM NEW.plan_id OR (OLD.plan_id IS NULL AND NEW.plan_id IS NOT NULL)) OR NOT (OLD.plan_subscription_id IS NOT DISTINCT FROM NEW.plan_subscription_id OR (OLD.plan_subscription_id IS NULL AND NEW.plan_subscription_id IS NOT NULL)) OR NOT (OLD.entry_access_point_id IS NOT DISTINCT FROM NEW.entry_access_point_id OR (OLD.entry_access_point_id IS NULL AND NEW.entry_access_point_id IS NOT NULL)) OR NOT (OLD.billing_scope_ref IS NOT DISTINCT FROM NEW.billing_scope_ref OR (OLD.billing_scope_ref IS NULL AND NEW.billing_scope_ref IS NOT NULL)) OR NOT (OLD.provider_id IS NOT DISTINCT FROM NEW.provider_id OR (OLD.provider_id IS NULL AND NEW.provider_id IS NOT NULL)) OR NOT (OLD.tar_model IS NOT DISTINCT FROM NEW.tar_model OR (OLD.tar_model IS NULL AND NEW.tar_model IS NOT NULL)) THEN RAISE EXCEPTION 'request_logs immutable fields cannot be updated' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "request_logs_controlled_update" ON "request_logs";
CREATE TRIGGER "request_logs_controlled_update" BEFORE UPDATE ON "request_logs" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_request_log_update"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_archive_lifecycle"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.archive_month IS DISTINCT FROM NEW.archive_month OR OLD.format_version IS DISTINCT FROM NEW.format_version OR OLD.schema_version IS DISTINCT FROM NEW.schema_version OR OLD.row_count IS DISTINCT FROM NEW.row_count OR OLD.compressed_bytes IS DISTINCT FROM NEW.compressed_bytes OR OLD.uncompressed_bytes IS DISTINCT FROM NEW.uncompressed_bytes OR OLD.object_key IS DISTINCT FROM NEW.object_key OR OLD.object_sha256 IS DISTINCT FROM NEW.object_sha256 OR OLD.manifest_object_key IS DISTINCT FROM NEW.manifest_object_key OR OLD.manifest_sha256 IS DISTINCT FROM NEW.manifest_sha256 OR OLD.created_at IS DISTINCT FROM NEW.created_at OR (OLD.status IS NOT DISTINCT FROM NEW.status AND (OLD.uploaded_at IS DISTINCT FROM NEW.uploaded_at OR OLD.verified_at IS DISTINCT FROM NEW.verified_at OR OLD.purged_at IS DISTINCT FROM NEW.purged_at)) OR NOT (OLD.status IS NOT DISTINCT FROM NEW.status OR (OLD.status = 'generated' AND NEW.status = 'uploaded') OR (OLD.status = 'uploaded' AND NEW.status = 'verified') OR (OLD.status = 'verified' AND NEW.status = 'purged')) THEN RAISE EXCEPTION '% invalid update', TG_TABLE_NAME USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "request_log_archives_controlled_update" ON "request_log_archives";
CREATE TRIGGER "request_log_archives_controlled_update" BEFORE UPDATE ON "request_log_archives" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_archive_lifecycle"();
DROP TRIGGER IF EXISTS "billing_provider_cost_archives_controlled_update" ON "billing_provider_cost_archives";
CREATE TRIGGER "billing_provider_cost_archives_controlled_update" BEFORE UPDATE ON "billing_provider_cost_archives" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_archive_lifecycle"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_authority_product_update"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.code IS DISTINCT FROM NEW.code OR OLD.version IS DISTINCT FROM NEW.version OR OLD.created_by_owner_user_id IS DISTINCT FROM NEW.created_by_owner_user_id OR OLD.created_at IS DISTINCT FROM NEW.created_at OR NOT ((OLD.lifecycle = 'draft' AND NEW.lifecycle IN ('draft','listed')) OR (OLD.lifecycle = 'listed' AND NEW.lifecycle IN ('listed','closed')) OR (OLD.lifecycle = 'closed' AND NEW.lifecycle = 'closed')) OR (OLD.lifecycle <> 'draft' AND (OLD.display_name IS DISTINCT FROM NEW.display_name OR OLD.effect_code IS DISTINCT FROM NEW.effect_code OR OLD.grant_units IS DISTINCT FROM NEW.grant_units OR OLD.purchase_amount_units IS DISTINCT FROM NEW.purchase_amount_units OR OLD.grant_duration_seconds IS DISTINCT FROM NEW.grant_duration_seconds OR OLD.max_lifetime_purchases_per_user IS DISTINCT FROM NEW.max_lifetime_purchases_per_user OR OLD.max_unconsumed_units_per_user IS DISTINCT FROM NEW.max_unconsumed_units_per_user OR OLD.max_current_owned_teams IS DISTINCT FROM NEW.max_current_owned_teams OR OLD.max_lifetime_created_teams IS DISTINCT FROM NEW.max_lifetime_created_teams OR OLD.refund_mode IS DISTINCT FROM NEW.refund_mode OR OLD.refund_deadline_seconds IS DISTINCT FROM NEW.refund_deadline_seconds OR OLD.settlement_hold_seconds IS DISTINCT FROM NEW.settlement_hold_seconds OR OLD.seller_scope_ref IS DISTINCT FROM NEW.seller_scope_ref)) THEN RAISE EXCEPTION 'authority_products invalid state transition' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "authority_products_controlled_update" ON "authority_products";
CREATE TRIGGER "authority_products_controlled_update" BEFORE UPDATE ON "authority_products" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_authority_product_update"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_authority_grant_update"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.beneficiary_user_id IS DISTINCT FROM NEW.beneficiary_user_id OR OLD.role_domain IS DISTINCT FROM NEW.role_domain OR OLD.role_code IS DISTINCT FROM NEW.role_code OR OLD.role_scope_id IS DISTINCT FROM NEW.role_scope_id OR OLD.source_kind IS DISTINCT FROM NEW.source_kind OR OLD.source_purchase_id IS DISTINCT FROM NEW.source_purchase_id OR OLD.source_product_code_snapshot IS DISTINCT FROM NEW.source_product_code_snapshot OR OLD.source_product_version_snapshot IS DISTINCT FROM NEW.source_product_version_snapshot OR OLD.source_origin_id_snapshot IS DISTINCT FROM NEW.source_origin_id_snapshot OR OLD.max_current_owned_teams_snapshot IS DISTINCT FROM NEW.max_current_owned_teams_snapshot OR OLD.max_lifetime_created_teams_snapshot IS DISTINCT FROM NEW.max_lifetime_created_teams_snapshot OR OLD.issued_by_user_id IS DISTINCT FROM NEW.issued_by_user_id OR OLD.effective_start IS DISTINCT FROM NEW.effective_start OR OLD.effective_end IS DISTINCT FROM NEW.effective_end OR OLD.created_at IS DISTINCT FROM NEW.created_at OR NOT (OLD.lifecycle = 'active' AND NEW.lifecycle = 'canceled' AND NEW.canceled_at IS NOT NULL AND NEW.canceled_by_user_id IS NOT NULL AND NEW.cancel_reason_code IS NOT NULL) THEN RAISE EXCEPTION 'authority_grants invalid state transition' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "authority_grants_controlled_update" ON "authority_grants";
CREATE TRIGGER "authority_grants_controlled_update" BEFORE UPDATE ON "authority_grants" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_authority_grant_update"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_team_provider_entitlement_update"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.team_id IS DISTINCT FROM NEW.team_id OR OLD.source_kind IS DISTINCT FROM NEW.source_kind OR OLD.source_authority_purchase_id IS DISTINCT FROM NEW.source_authority_purchase_id OR OLD.source_authority_product_id IS DISTINCT FROM NEW.source_authority_product_id OR OLD.source_product_code_snapshot IS DISTINCT FROM NEW.source_product_code_snapshot OR OLD.source_product_version_snapshot IS DISTINCT FROM NEW.source_product_version_snapshot OR OLD.source_product_display_name_snapshot IS DISTINCT FROM NEW.source_product_display_name_snapshot OR OLD.buyer_user_id IS DISTINCT FROM NEW.buyer_user_id OR OLD.issued_by_user_id IS DISTINCT FROM NEW.issued_by_user_id OR OLD.effective_start IS DISTINCT FROM NEW.effective_start OR OLD.effective_end IS DISTINCT FROM NEW.effective_end OR OLD.idempotency_key_hash IS DISTINCT FROM NEW.idempotency_key_hash OR OLD.request_hash IS DISTINCT FROM NEW.request_hash OR OLD.created_at IS DISTINCT FROM NEW.created_at OR NOT (OLD.lifecycle = 'active' AND NEW.lifecycle = 'canceled' AND NEW.canceled_at IS NOT NULL AND NEW.canceled_by_user_id IS NOT NULL AND NEW.cancel_reason_code IS NOT NULL) THEN RAISE EXCEPTION 'team_provider_entitlements invalid state transition' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "team_provider_entitlements_controlled_update" ON "team_provider_entitlements";
CREATE TRIGGER "team_provider_entitlements_controlled_update" BEFORE UPDATE ON "team_provider_entitlements" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_team_provider_entitlement_update"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_team_invite_link_capacity"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'INSERT' THEN IF NEW.status = 'enabled' AND (NEW.used_count IS NULL OR NEW.used_count < 0 OR (NEW.max_uses IS NOT NULL AND (NEW.max_uses < 1 OR NEW.max_uses > 1000 OR NEW.used_count >= NEW.max_uses))) THEN RAISE EXCEPTION 'enabled team invite link requires remaining capacity' USING ERRCODE = '55000'; END IF; ELSE IF OLD.active_limit_exempt IS DISTINCT FROM NEW.active_limit_exempt OR (OLD.max_uses IS NOT NULL AND OLD.max_uses IS DISTINCT FROM NEW.max_uses) OR (OLD.used_count IS NOT NULL AND (NEW.used_count IS NULL OR NEW.used_count < OLD.used_count)) OR (NEW.max_uses IS NOT NULL AND (NEW.max_uses < 1 OR NEW.max_uses > 1000)) OR (NEW.used_count IS NOT NULL AND (NEW.used_count < 0 OR (NEW.max_uses IS NOT NULL AND NEW.used_count > NEW.max_uses))) OR (NEW.status = 'enabled' AND (NEW.used_count IS NULL OR (NEW.max_uses IS NOT NULL AND NEW.used_count >= NEW.max_uses))) THEN RAISE EXCEPTION 'invalid team invite link capacity update' USING ERRCODE = '55000'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "team_invite_links_capacity_insert" ON "team_invite_links";
CREATE TRIGGER "team_invite_links_capacity_insert" BEFORE INSERT ON "team_invite_links" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_team_invite_link_capacity"();
DROP TRIGGER IF EXISTS "team_invite_links_capacity_update" ON "team_invite_links";
CREATE TRIGGER "team_invite_links_capacity_update" BEFORE UPDATE ON "team_invite_links" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_team_invite_link_capacity"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_public_hostname"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME = 'instance_public_hosts' AND TG_OP = 'UPDATE' AND OLD.hostname IS DISTINCT FROM NEW.hostname THEN RAISE EXCEPTION 'instance_public_hosts hostname is immutable' USING ERRCODE = '55000'; END IF; IF TG_TABLE_NAME = 'instance_public_hosts' AND TG_OP = 'INSERT' AND EXISTS (SELECT 1 FROM "domain_bindings" WHERE "hostname" = NEW.hostname) THEN RAISE EXCEPTION 'instance_public_hosts hostname conflicts with domain_bindings' USING ERRCODE = '55000'; END IF; IF TG_TABLE_NAME = 'domain_bindings' AND EXISTS (SELECT 1 FROM "instance_public_hosts" WHERE "hostname" = NEW.hostname) THEN RAISE EXCEPTION 'domain_bindings hostname conflicts with instance_public_hosts' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "instance_public_hosts_hostname_immutable" ON "instance_public_hosts";
CREATE TRIGGER "instance_public_hosts_hostname_immutable" BEFORE UPDATE OF hostname ON "instance_public_hosts" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_public_hostname"();
DROP TRIGGER IF EXISTS "instance_public_hosts_domain_binding_conflict" ON "instance_public_hosts";
CREATE TRIGGER "instance_public_hosts_domain_binding_conflict" BEFORE INSERT ON "instance_public_hosts" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_public_hostname"();
DROP TRIGGER IF EXISTS "domain_bindings_public_host_insert_conflict" ON "domain_bindings";
CREATE TRIGGER "domain_bindings_public_host_insert_conflict" BEFORE INSERT ON "domain_bindings" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_public_hostname"();
DROP TRIGGER IF EXISTS "domain_bindings_public_host_update_conflict" ON "domain_bindings";
CREATE TRIGGER "domain_bindings_public_host_update_conflict" BEFORE UPDATE OF hostname ON "domain_bindings" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_public_hostname"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_plan_catalog_status"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.plan_status NOT IN ('enabled','closed','disabled') OR NEW.catalog_status NOT IN ('listed','unlisted') OR (NEW.catalog_status = 'listed' AND (NEW.plan_status <> 'enabled' OR NEW.billing_mode <> 'prepaid' OR NEW.duration_seconds <= 0 OR round((NEW.purchase_amount * 1000000)::numeric) <= 0)) THEN RAISE EXCEPTION 'invalid Plan status/catalog combination' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "plans_validate_insert" ON "plans";
DROP TRIGGER IF EXISTS "plans_validate_update" ON "plans";
CREATE TRIGGER "plans_validate_insert" BEFORE INSERT ON "plans" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_plan_catalog_status"();
CREATE TRIGGER "plans_validate_update" BEFORE UPDATE ON "plans" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_plan_catalog_status"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_card_activation_batch_transition"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.reference_code IS DISTINCT FROM NEW.reference_code OR OLD.card_type IS DISTINCT FROM NEW.card_type OR OLD.plan_id IS DISTINCT FROM NEW.plan_id OR OLD.credit_product_id IS DISTINCT FROM NEW.credit_product_id OR OLD.credit_amount_units IS DISTINCT FROM NEW.credit_amount_units OR OLD.quantity IS DISTINCT FROM NEW.quantity OR OLD.redeem_expires_at IS DISTINCT FROM NEW.redeem_expires_at OR OLD.export_seed_ciphertext IS DISTINCT FROM NEW.export_seed_ciphertext OR OLD.export_key_version IS DISTINCT FROM NEW.export_key_version OR OLD.idempotency_key_hash IS DISTINCT FROM NEW.idempotency_key_hash OR OLD.request_hash IS DISTINCT FROM NEW.request_hash OR OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id OR OLD.created_at IS DISTINCT FROM NEW.created_at OR NOT (OLD.revoked_at IS NOT DISTINCT FROM NEW.revoked_at AND OLD.revoked_by_user_id IS NOT DISTINCT FROM NEW.revoked_by_user_id AND OLD.revocation_reason IS NOT DISTINCT FROM NEW.revocation_reason OR OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL AND NEW.revoked_by_user_id IS NOT NULL AND NEW.revocation_reason IS NOT NULL) THEN RAISE EXCEPTION 'card_activation_batches invalid state transition' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "card_activation_batches_controlled_update" ON "card_activation_batches";
CREATE TRIGGER "card_activation_batches_controlled_update" BEFORE UPDATE ON "card_activation_batches" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_card_activation_batch_transition"();
CREATE OR REPLACE FUNCTION "friday_relay_validate_card_activation_code_transition"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.id IS DISTINCT FROM NEW.id OR OLD.batch_id IS DISTINCT FROM NEW.batch_id OR OLD.ordinal IS DISTINCT FROM NEW.ordinal OR OLD.code_hash IS DISTINCT FROM NEW.code_hash OR OLD.code_suffix IS DISTINCT FROM NEW.code_suffix OR OLD.created_at IS DISTINCT FROM NEW.created_at OR NOT ((OLD.revoked_at IS NOT DISTINCT FROM NEW.revoked_at AND OLD.revoked_by_user_id IS NOT DISTINCT FROM NEW.revoked_by_user_id AND OLD.revocation_reason IS NOT DISTINCT FROM NEW.revocation_reason) OR (OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL AND NEW.revoked_by_user_id IS NOT NULL AND NEW.revocation_reason IS NOT NULL)) OR NOT ((OLD.redeemed_at IS NOT DISTINCT FROM NEW.redeemed_at AND OLD.redeemed_by_user_id IS NOT DISTINCT FROM NEW.redeemed_by_user_id AND OLD.redeemed_card_id IS NOT DISTINCT FROM NEW.redeemed_card_id) OR (OLD.redeemed_at IS NULL AND NEW.redeemed_at IS NOT NULL AND NEW.redeemed_by_user_id IS NOT NULL AND NEW.redeemed_card_id IS NOT NULL)) THEN RAISE EXCEPTION 'card_activation_codes invalid state transition' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS "card_activation_codes_controlled_update" ON "card_activation_codes";
CREATE TRIGGER "card_activation_codes_controlled_update" BEFORE UPDATE ON "card_activation_codes" FOR EACH ROW EXECUTE FUNCTION "friday_relay_validate_card_activation_code_transition"();
CREATE OR REPLACE FUNCTION "friday_relay_bump_agent_catalog_revision"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE "agent_catalog_revisions" SET "revision" = "revision" + 1 WHERE "id" = 1; RETURN NULL; END $$;
